// Generated by `just generate` from `src/plugins/claudetto/slices/gc/lab/gc.test.ts`. Edit the source and run `just generate`.
// Lab tests of the `gc` hooks: the record of the outputs, the sweep at session start and session end, and the command `claudetto:gc`.
// The stubs of `fs`, `process.run`, and `ui.log` are the test's own, so no file is written, no sweep runs, and no path is removed.
// The file is self-contained, because `just generate` copies it to `tests/` of the plugin, where it cannot import a relative file.

import type { On } from "claude-code";
import { type Engine, expect, mock, test } from "claude-code/testing";

const RECORD_FILE = "/home/me/.claudetto/gc/sess-1.json";

/** What the stubs saw: the files that the hook wrote, and the argument vectors that it ran. */
type Seen = {
  writes: Record<string, string>;
  runs: string[][];
  logs: string[];
};

/** Stubs for one test. `bash` is the `stdout` that the `Bash` call gives, or its whole result. `slowRead` makes each read of a record file wait. */
const stub = (
  on: On,
  bash: string | Record<string, unknown> = "",
  slowRead = false,
): Seen => {
  const seen: Seen = { writes: {}, runs: [], logs: [] };
  mock.env(on, { HOME: "/home/me" });
  on("session.id", () => ({ value: "sess-1" }));
  on("session.cwd", () => ({ value: "/work/app" }));
  on("clock.now", () => ({ value: 1_000_000 }));
  on("fs.exists", (_$, e) => ({ value: e.path in seen.writes }));
  on("fs.read", async (_$, e) => {
    const text = seen.writes[e.path] ?? "";
    if (slowRead) await new Promise((done) => setTimeout(done, 10));
    return { value: text };
  });
  on("fs.write", (_$, e) => {
    seen.writes[e.path] = e.text;
    return { value: undefined };
  });
  on("process.run", (_$, e) => {
    // The bundle holds the hooks of other slices too, and their commands are not the test's concern.
    if (e.argv.some((word) => word.endsWith("claudetto-gc")))
      seen.runs.push(
        e.argv.map((word) => word.split("/").pop() as string).slice(2),
      );
    return {
      value: {
        exitCode: 0,
        stdout: "Removed 0 paths, freed 0 B.\n",
        stderr: "",
        isStdoutTruncated: false,
        isStderrTruncated: false,
      },
    };
  });
  on("ui.log", (_$, e) => {
    seen.logs.push(e.text);
    return { value: undefined };
  });
  let calls = 0;
  on("tool.call", () => ({
    result:
      typeof bash === "string"
        ? { stdout: bash.replace("{n}", String(++calls)), stderr: "" }
        : bash,
  }));
  on("session.start", (_$, e) => ({ cwd: e.cwd }));
  on("session.end", (_$, e) => ({ sessionId: e.sessionId }));
  on("command.run", () => ({ text: "core" }));
  return seen;
};

const bash = ($: Engine, command: string) =>
  $.tool.call({ tool: "Bash", command });

test("`mktemp -d` writes a record with the path and the session id", async ($: Engine, on: On) => {
  const seen = stub(on, "/tmp/tmp.abc123\n");
  await bash($, "mktemp -d");
  const records = JSON.parse(seen.writes[RECORD_FILE] ?? "[]");
  expect(records).toEqual([
    {
      path: "/tmp/tmp.abc123",
      kind: "temp",
      session: "sess-1",
      cwd: "/work/app",
      time: 1_000_000,
    },
  ]);
});

test("a second `mktemp -d` adds to the record of the session", async ($: Engine, on: On) => {
  const seen = stub(on, "/tmp/tmp.one\n");
  await bash($, "mktemp -d");
  await bash($, "mktemp -d");
  expect(JSON.parse(seen.writes[RECORD_FILE] ?? "[]")).toHaveLength(1);
});

test("a `Bash` call that makes no output writes no record", async ($: Engine, on: On) => {
  const seen = stub(on, "/tmp/tmp.abc123\n");
  await bash($, "ls /tmp");
  expect(seen.writes).toEqual({});
});

test("a `Write` to a temp folder records a scratch file", async ($: Engine, on: On) => {
  const seen = stub(on);
  await $.tool.call({ tool: "Write", file_path: "/tmp/a.txt", content: "x" });
  expect(JSON.parse(seen.writes[RECORD_FILE] ?? "[]")[0]).toMatchObject({
    path: "/tmp/a.txt",
    kind: "scratch",
  });
});

test("`mktemp` records only the temp paths", async ($: Engine, on: On) => {
  const seen = stub(on, "/home/me/project/file\n/tmp/tmp.ok\n");
  await bash($, "mktemp -d && pwd");
  const records = JSON.parse(seen.writes[RECORD_FILE] ?? "[]");
  expect(records.map((r: { path: string }) => r.path)).toEqual(["/tmp/tmp.ok"]);
});

test("the output file of a background task is recorded as a task", async ($: Engine, on: On) => {
  const seen = stub(on, {
    stdout: "",
    stderr: "",
    backgroundTaskId: "b1",
    backgroundOutputPath: "/tmp/claude-1/sess-1/tasks/b1.output",
  });
  await bash($, "sleep 100");
  expect(JSON.parse(seen.writes[RECORD_FILE] ?? "[]")[0]).toMatchObject({
    path: "/tmp/claude-1/sess-1/tasks/b1.output",
    kind: "task",
    session: "sess-1",
  });
});

test("two calls at the same time both reach the record", async ($: Engine, on: On) => {
  const seen = stub(on, "/tmp/tmp.{n}\n", true);
  await Promise.all([bash($, "mktemp -d"), bash($, "mktemp -d")]);
  expect(JSON.parse(seen.writes[RECORD_FILE] ?? "[]")).toHaveLength(2);
});

const start = ($: Engine) =>
  $.session.start({ cwd: "/work/app", surface: null, isInteractive: false });

test("session start passes the session on", async ($: Engine, on: On) => {
  stub(on);
  const out = await start($);
  expect(out.cwd).toBe("/work/app");
});

test("session start runs the sweep without the ending option", async ($: Engine, on: On) => {
  const seen = stub(on);
  await start($);
  expect(seen.runs).toEqual([["claudetto-gc"]]);
  expect(seen.logs[0]).toContain("Removed 0 paths");
});

const end = ($: Engine) =>
  $.session.end({
    reason: "other",
    sessionId: "sess-1",
    resume: { id: "sess-1" },
  } as never);

test("session end passes the end on", async ($: Engine, on: On) => {
  stub(on);
  const out = await end($);
  expect(out.sessionId).toBe("sess-1");
});

test("session end runs the sweep with the id of the ending session", async ($: Engine, on: On) => {
  const seen = stub(on);
  await end($);
  expect(seen.runs).toEqual([["claudetto-gc", "--ending", "sess-1"]]);
});

const typed = ($: Engine, command: string, args = "") =>
  $.command.run({
    command,
    args,
    origin: { kind: "composer" },
    presentation: { isFullscreen: false, columns: 80 },
  });

// biome-ignore lint/plugin: a test name that a `slice.ts` file references
test("the command `claudetto:gc` passes the dry-run option to the CLI", async ($: Engine, on: On) => {
  const seen = stub(on);
  const out = await typed($, "claudetto:gc", "--dry-run");
  expect(out.text).toContain("Removed 0 paths");
  expect(seen.runs).toEqual([["claudetto-gc", "--dry-run"]]);
});

test("another command runs unchanged", async ($: Engine, on: On) => {
  const seen = stub(on);
  const out = await typed($, "usage");
  expect(out.text).toBe("core");
  expect(seen.runs).toEqual([]);
});
